# Biology 2: reproduction (flowering plants, humans, reproductive health),
# genetics and evolution (NEET units 6 and 7). Key written first; numbers
# asserted below.
from math import isclose

# DNA with 23% G: A = (100 - 2 x 23) / 2
assert (100 - 2 * 23) / 2 == 27
# Hardy-Weinberg: q^2 = 0.04 -> 2pq
q = 0.2
assert isclose(2 * (1 - q) * q, 0.32) and isclose((1 - q) * q, 0.16)
# one primary spermatocyte -> 4 sperm
assert 2 * 2 == 4

